package com.ruoyi.medical.persistence;
import com.ruoyi.medical.contracts.*;import com.ruoyi.medical.identity.ApplicationSessionIdentity;import com.ruoyi.medical.persistence.mapper.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.ObjectProvider;import org.springframework.jdbc.core.*;import org.springframework.test.util.ReflectionTestUtils;import javax.sql.DataSource;import java.util.*;import java.util.function.Function;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
/** Actual original object recovery + registration reader + publication authority. Underlying professional and lifecycle proofs are explicit separate fixture boundaries. */
class PublicationHistoricalAuthorityTest {
 PublicationRegistrationTest fixture;FormalAgentPublicationObjectLedgerTest f;EnterpriseAccess access;ApplicationSessionIdentity.Verified subject;FormalAgentPublicationAuthorization auth;AgentPublicationAuthority service;PublicationEvidenceRevalidation evidence;
 @BeforeEach void setup()throws Exception{
  fixture=new PublicationRegistrationTest();fixture.setup();f=fixture.f;fixture.service.finish(f.a,fixture.attempt,fixture.transfer,f.proof);f.end();
  doAnswer(i->List.of(Map.entry(f.row.actor(),f.row.key()))).when(f.db).query(startsWith("SELECT created_by,idempotency_key FROM formal_agent_publication_intent"),any(RowMapper.class),any(Object[].class));
  access=mock(EnterpriseAccess.class);subject=mock(ApplicationSessionIdentity.Verified.class);var user=mock(com.ruoyi.medical.identity.BusinessSessionProtocol.User.class);when(user.user_id()).thenReturn(f.actor);when(subject.user()).thenReturn(user);
  when(access.execute(eq(subject),any())).thenAnswer(i->{f.begin();try{return ((Function<EnterpriseAccess.Admission,Object>)i.getArgument(1)).apply(f.a);}finally{f.end();}});
  var acceptances=mock(FormalAgentAcceptanceStore.class);var loaded=mock(FormalAgentAcceptanceStore.Loaded.class);var row=mock(FormalAgentAcceptanceMapper.Acceptance.class);when(row.tenantId()).thenReturn(f.row.tenant());when(row.releaseId()).thenReturn(f.row.release());when(row.acceptanceId()).thenReturn(f.row.acceptance());when(row.contentSha256()).thenReturn(f.row.acceptanceHash());when(loaded.row()).thenReturn(row);when(loaded.content()).thenReturn(f.json.object());when(acceptances.metadata(eq(f.a),any(),eq("AGENT_PUBLICATION"))).thenReturn(loaded);
  auth=mock(FormalAgentPublicationAuthorization.class);when(auth.require(eq(f.a),any(),eq(false),anyBoolean(),any())).thenReturn(f.proof);when(f.proof.candidateStatus()).thenReturn("PUBLISHED");
  evidence=mock(PublicationEvidenceRevalidation.class);var prepared=mock(PublicationEvidenceRevalidation.Prepared.class);when(evidence.prepare(eq(subject),eq("1"),any(),anyBoolean())).thenReturn(prepared);ObjectProvider<PublicationEvidenceRevalidation> ep=mock(ObjectProvider.class);when(ep.getIfAvailable()).thenReturn(evidence);
  ObjectProvider<RuntimeObjectTransport> tp=mock(ObjectProvider.class);when(tp.getIfAvailable()).thenReturn(new RuntimeObjectTransport(()->fixture.writer,fixture.directory,16*1024*1024));
  service=new AgentPublicationAuthority(access,mock(DataSource.class),acceptances,auth,f.ledger,fixture.service,ep,tp,f.resources,f.formal,f.json,mock(FormalAgentPublicationLifecycle.class));
  var db=mock(JdbcTemplate.class);ReflectionTestUtils.setField(service,"db",db);when(db.query(anyString(),any(RowMapper.class),any(Object[].class))).thenReturn(List.of(new PermissionProtocol.Basis(f.row.acceptance(),f.row.acceptanceHash())));
 }
 @AfterEach void close()throws Exception{f.begin();fixture.cleanup();}
 AgentPublicationAuthority.PreparedPublication prepare(boolean h)throws Exception{return service.prepare(subject,"1",f.row.release(),"TASK_CREATION",h);}
 @Test void currentAndHistoricalProofsCannotBeInterchanged()throws Exception{var current=prepare(false);var history=prepare(true);f.begin();try{service.require(f.a,f.row.release(),"TASK_CREATION",current).requireUnchanged();service.requireHistoricalRead(f.a,f.row.release(),"TASK_CREATION",history).requireUnchanged();assertThrows(TenantAccessException.class,()->service.require(f.a,f.row.release(),"TASK_CREATION",history));assertThrows(TenantAccessException.class,()->service.requireHistoricalRead(f.a,f.row.release(),"TASK_CREATION",current));}finally{f.end();}}
 @Test void disabledReleaseCanBeReadHistoricallyButCannotExecute()throws Exception{when(f.proof.candidateStatus()).thenReturn("DISABLED");var current=prepare(false);var history=prepare(true);f.begin();try{assertThrows(TenantAccessException.class,()->service.require(f.a,f.row.release(),"TASK_CREATION",current));service.requireHistoricalRead(f.a,f.row.release(),"TASK_CREATION",history);}finally{f.end();}}
 @Test void historicalReadActuallyRecoversOriginalObjectAndNeverWrites()throws Exception{clearInvocations(fixture.writer);prepare(true);verify(fixture.writer).recoverVerified(any(),any());verify(fixture.writer,never()).writeVerified(any(),any(),any());}
 @Test void missingPhysicalObjectCannotProduceHistoricalProof()throws Exception{when(fixture.writer.recoverVerified(any(),any())).thenThrow(new TenantAccessException(ErrorCode.OBJECT_UNAVAILABLE));assertThrows(Exception.class,()->prepare(true));}
 @Test void changedAuditAfterPreparationRejectsConsumer()throws Exception{var p=prepare(true);fixture.first("audit_event").put("resource_ref","{}");f.begin();try{assertThrows(TenantAccessException.class,()->service.requireHistoricalRead(f.a,f.row.release(),"TASK_CREATION",p));}finally{f.end();}}
 @Test void wrongPurposeCannotReusePreparedOriginal()throws Exception{var p=prepare(true);f.begin();try{assertThrows(TenantAccessException.class,()->service.requireHistoricalRead(f.a,f.row.release(),"RUN_CREATION",p));}finally{f.end();}}
}
